<?php
session_start();require_once '../config/database.php';require_once 'lib.php';require_once 'assignment_service.php';
if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;}
$railroad=ttOperationsRailroad($pdo,(int)$_SESSION['user_id']);$railroadId=(int)$railroad['id'];$sessionId=(int)($_GET['id']??$_POST['session_id']??0);$error='';
$stmt=$pdo->prepare('SELECT * FROM operating_sessions WHERE id=? AND railroad_id=?');$stmt->execute([$sessionId,$railroadId]);$session=$stmt->fetch(PDO::FETCH_ASSOC);if(!$session){http_response_code(404);die('Operating session not found.');}
if($_SERVER['REQUEST_METHOD']==='POST')try{
    ttOperationsRequireCsrf();$action=(string)($_POST['action']??'');
    if($action==='add_assignment'){
        if(!ttOperatingSessionIsEditable((string)$session['status']))throw new RuntimeException('This operating session is frozen and assignments cannot be created.');$pdo->beginTransaction();$stmt=$pdo->prepare('SELECT status FROM operating_sessions WHERE id=? AND railroad_id=? FOR UPDATE');$stmt->execute([$sessionId,$railroadId]);if(!ttOperatingSessionIsEditable((string)$stmt->fetchColumn()))throw new RuntimeException('This operating session became frozen and the assignment was not created.');$data=ttAssignmentNormalizeInput($pdo,$railroadId,$sessionId,$_POST);$stmt=$pdo->prepare('SELECT COALESCE(MAX(sequence_number),0)+1 FROM operation_assignments WHERE session_id=? FOR UPDATE');$stmt->execute([$sessionId]);$sequence=(int)$stmt->fetchColumn();$job=$data['job'];$number=$session['session_number'].'-'.ttAssignmentSuffix($sequence);$status='draft';
        $stmt=$pdo->prepare('INSERT INTO operation_assignments(railroad_id,session_id,job_template_id,assignment_number,sequence_number,title_snapshot,type_snapshot,description_snapshot,operating_pattern,status,operating_base_industry_id,starting_track,start_method,prepared_cut_id,requested_car_count,prepared_cut_car_count,difficulty,crew_name,predecessor_assignment_id,dependency_mode,end_plan,end_industry_id,end_track,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
        $stmt->execute([$railroadId,$sessionId,$data['job_id'],$number,$sequence,$job['job_name'],$job['job_type'],$job['description'],$data['pattern'],$status,$data['base_id'],$data['starting_track'],$data['start_method'],$data['cut_id'],$data['requested'],$data['prepared_cut_count'],$data['difficulty'],$data['crew'],$data['predecessor'],$data['dependency'],$data['end_plan'],$data['end_id'],$data['end_track'],$data['notes']]);$assignmentId=(int)$pdo->lastInsertId();$reserved=ttReservedEquipmentIds($pdo,$railroadId,$assignmentId);ttAssignmentReplaceLocomotives($pdo,$assignmentId,$railroadId,$data['locomotive_ids'],$reserved);ttAssignmentReplaceStartingCars($pdo,$assignmentId,$railroadId,$data,$reserved);$pdo->commit();header('Location: session_edit.php?id='.$sessionId);exit;
    }
    if($action==='start_session'){
        if(!ttOperatingSessionIsEditable((string)$session['status']))throw new RuntimeException('This operating session cannot be started from its current status.');$stmt=$pdo->prepare("SELECT a.id,a.status,a.predecessor_assignment_id,(SELECT sl.status FROM operation_switch_lists sl WHERE sl.assignment_id=a.id AND sl.railroad_id=a.railroad_id ORDER BY sl.revision_number DESC LIMIT 1) latest_list_status FROM operation_assignments a WHERE a.session_id=? AND a.railroad_id=?");$stmt->execute([$sessionId,$railroadId]);[$canStart,$reason]=ttSessionStartReadiness($stmt->fetchAll(PDO::FETCH_ASSOC));if(!$canStart)throw new RuntimeException($reason);$stmt=$pdo->prepare("UPDATE operating_sessions SET status='in_progress',started_at=COALESCE(started_at,NOW()) WHERE id=? AND railroad_id=? AND status IN('draft','ready')");$stmt->execute([$sessionId,$railroadId]);if(!$stmt->rowCount())throw new RuntimeException('This session cannot be started from its current status.');header('Location: session_edit.php?id='.$sessionId);exit;
    }
    throw new RuntimeException('Invalid Session Builder action.');
}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
$jobsStmt=$pdo->prepare('SELECT id,job_name,job_type FROM jobs WHERE railroad_id=? AND active=1 ORDER BY job_name');$jobsStmt->execute([$railroadId]);$jobs=$jobsStmt->fetchAll(PDO::FETCH_ASSOC);
$industriesStmt=$pdo->prepare('SELECT id,industry_name FROM industries WHERE railroad_id=? AND active=1 ORDER BY industry_name');$industriesStmt->execute([$railroadId]);$industries=$industriesStmt->fetchAll(PDO::FETCH_ASSOC);
$locosStmt=$pdo->prepare("SELECT id,reporting_marks,road_number,road_name,current_track FROM equipment WHERE railroad_id=? AND active=1 AND equipment_class='Locomotive' ORDER BY reporting_marks,road_number");$locosStmt->execute([$railroadId]);$locomotives=$locosStmt->fetchAll(PDO::FETCH_ASSOC);
$carsStmt=$pdo->prepare("SELECT e.id,e.reporting_marks,e.road_number,e.equipment_type,e.current_industry_id,e.current_track,i.industry_name FROM equipment e JOIN industries i ON i.id=e.current_industry_id AND i.railroad_id=e.railroad_id WHERE e.railroad_id=? AND e.active=1 AND COALESCE(e.equipment_class,'')<>'Locomotive' AND NOT EXISTS(SELECT 1 FROM operation_assignment_starting_cars ac JOIN operation_assignments a ON a.id=ac.assignment_id WHERE ac.equipment_id=e.id AND a.railroad_id=e.railroad_id AND a.status IN('draft','ready','waiting','in_progress','needs_review')) ORDER BY e.reporting_marks,e.road_number");$carsStmt->execute([$railroadId]);$startingCars=$carsStmt->fetchAll(PDO::FETCH_ASSOC);
$cutsStmt=$pdo->prepare("SELECT c.*,COUNT(pc.equipment_id) car_count,i.industry_name FROM prepared_cuts c JOIN industries i ON i.id=c.current_industry_id AND i.railroad_id=c.railroad_id LEFT JOIN prepared_cut_cars pc ON pc.prepared_cut_id=c.id WHERE c.railroad_id=? AND c.status='ready' AND NOT EXISTS(SELECT 1 FROM prepared_cut_cars pc2 JOIN operation_assignment_starting_cars ac2 ON ac2.equipment_id=pc2.equipment_id JOIN operation_assignments a2 ON a2.id=ac2.assignment_id WHERE pc2.prepared_cut_id=c.id AND a2.railroad_id=c.railroad_id AND a2.status IN('draft','ready','waiting','in_progress','needs_review')) GROUP BY c.id ORDER BY c.cut_number");$cutsStmt->execute([$railroadId]);$cuts=$cutsStmt->fetchAll(PDO::FETCH_ASSOC);
$assignStmt=$pdo->prepare("SELECT a.*,? session_status,i.industry_name base_name,(SELECT COUNT(*) FROM operation_assignment_locomotives al WHERE al.assignment_id=a.id) locomotive_count,(SELECT COUNT(*) FROM operation_assignment_starting_cars ac WHERE ac.assignment_id=a.id) starting_car_count,(SELECT sl.id FROM operation_switch_lists sl WHERE sl.assignment_id=a.id AND sl.status<>'cancelled' ORDER BY sl.revision_number DESC LIMIT 1) switch_list_id,(SELECT sl.status FROM operation_switch_lists sl WHERE sl.assignment_id=a.id AND sl.status<>'cancelled' ORDER BY sl.revision_number DESC LIMIT 1) switch_list_status,(SELECT sl.status FROM operation_switch_lists sl WHERE sl.assignment_id=a.id ORDER BY sl.revision_number DESC LIMIT 1) latest_list_status,(SELECT sl.planned_move_count FROM operation_switch_lists sl WHERE sl.assignment_id=a.id AND sl.status<>'cancelled' ORDER BY sl.revision_number DESC LIMIT 1) planned_move_count,(SELECT COUNT(*) FROM operation_switch_lists sl WHERE sl.assignment_id=a.id AND sl.status IN('approved','in_progress','completed','needs_review')) frozen_list_count FROM operation_assignments a LEFT JOIN industries i ON i.id=a.operating_base_industry_id WHERE a.session_id=? AND a.railroad_id=? ORDER BY a.sequence_number");$assignStmt->execute([(string)$session['status'],$sessionId,$railroadId]);$assignments=$assignStmt->fetchAll(PDO::FETCH_ASSOC);[$canStart,$startReason]=ttSessionStartReadiness($assignments);if(!ttOperatingSessionIsEditable((string)$session['status'])){$canStart=false;$startReason='This operating session is frozen.';}$patterns=ttJobTypes();
?>
<?php include '../includes/header.php';?><title><?=ttHtml($session['session_number'])?> Session Builder</title><link rel="stylesheet" href="../assets/css/operations.css"></head><body><?php include '../includes/navbar.php';?><div class="tt-operations-shell"><?php include '../assets/components/sidebar.php';?><section class="tt-ops-page">
