-md-3 tt-field-end"><label class="form-label">End Track</label><input class="form-control" name="end_track" maxlength="120"></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="2"></textarea></div></div></details></div><div><button class="btn btn-primary">Add Assignment</button></div></form></div></div>
